namespace Durevo.Runtime;

// Initial typed VM. Programs are generated by the build tool, never accepted from users.
// This managed interpreter is inspectable; it is a baseline for future diversification/native execution.
public static class IntegerMachine
{
    public enum Operation
    {
        Nop, Constant, Argument, LoadLocal, StoreLocal, Dup, Pop,
        Add, Sub, Mul, Div, Rem, And, Or, Xor, Shl, Shr, ShrUnsigned, Neg, Not,
        Equal, Greater, Less, GreaterUnsigned, LessUnsigned,
        Jump, False, True, Eq, Ne, Ge, Gt, Le, Lt, GeUnsigned, GtUnsigned, LeUnsigned, LtUnsigned,
        Return, AddChecked, SubChecked, MulChecked, DivUnsigned, RemUnsigned,
        AddCheckedUnsigned, SubCheckedUnsigned, MulCheckedUnsigned,
        StringLength, StringChar, StringIndexOfChar, ConvertU2, StoreCharLocal, StoreBoolLocal
    }

    public static int Run(int[] program, int[] arguments, int localCount, int stackSize, int key) =>
        RunStrings(program, arguments, localCount, stackSize, key, System.Array.Empty<string>());
    public static int RunStrings(int[] program, int[] arguments, int localCount, int stackSize, int key, string[] strings)
    {
        var locals = new int[localCount];
        var stack = new int[stackSize];
        int pc = 0, sp = 0;
        while (true)
        {
            var op = (Operation)Decode(program, pc++, key);
            int operand = Decode(program, pc++, key);
            int a, b;
            switch (op)
            {
                case Operation.Nop: break;
                case Operation.Constant: stack[sp++] = operand; break;
                case Operation.Argument: stack[sp++] = arguments[operand]; break;
                case Operation.LoadLocal: stack[sp++] = locals[operand]; break;
                case Operation.StoreLocal: locals[operand] = stack[--sp]; break;
                case Operation.StoreCharLocal: locals[operand] = stack[--sp] & 65535; break;
                case Operation.StoreBoolLocal: locals[operand] = stack[--sp] & 255; break;
                case Operation.ConvertU2: stack[sp-1] &= 65535; break;
                case Operation.StringLength: stack[sp-1] = Text(strings,stack[sp-1]).Length; break;
                case Operation.StringChar:
                    b = stack[--sp]; a = stack[--sp]; stack[sp++] = Text(strings,a)[b]; break;
                case Operation.StringIndexOfChar:
                    b = stack[--sp]; a = stack[--sp]; stack[sp++] = Text(strings,a).IndexOf((char)b); break;
                case Operation.Dup: stack[sp] = stack[sp-1]; sp++; break;
                case Operation.Pop: --sp; break;
                case Operation.Neg: stack[sp-1] = unchecked(-stack[sp-1]); break;
                case Operation.Not: stack[sp-1] = ~stack[sp-1]; break;
                case Operation.Jump: pc = operand; break;
                case Operation.False: if (stack[--sp] == 0) pc = operand; break;
                case Operation.True: if (stack[--sp] != 0) pc = operand; break;
                case Operation.Return: return stack[--sp];
                default:
                    b = stack[--sp]; a = stack[--sp];
                    switch (op)
                    {
                        case Operation.Add: stack[sp++] = unchecked(a+b); break;
                        case Operation.Sub: stack[sp++] = unchecked(a-b); break;
                        case Operation.Mul: stack[sp++] = unchecked(a*b); break;
                        case Operation.Div: stack[sp++] = a/b; break;
                        case Operation.Rem: stack[sp++] = a%b; break;
                        case Operation.DivUnsigned: stack[sp++] = unchecked((int)((uint)a/(uint)b)); break;
                        case Operation.RemUnsigned: stack[sp++] = unchecked((int)((uint)a%(uint)b)); break;
                        case Operation.And: stack[sp++] = a&b; break;
                        case Operation.Or: stack[sp++] = a|b; break;
                        case Operation.Xor: stack[sp++] = a^b; break;
                        case Operation.Shl: stack[sp++] = a<<b; break;
                        case Operation.Shr: stack[sp++] = a>>b; break;
                        case Operation.ShrUnsigned: stack[sp++] = unchecked((int)((uint)a>>b)); break;
                        case Operation.Equal: stack[sp++] = a==b ? 1:0; break;
                        case Operation.Greater: stack[sp++] = a>b ? 1:0; break;
                        case Operation.Less: stack[sp++] = a<b ? 1:0; break;
                        case Operation.GreaterUnsigned: stack[sp++] = (uint)a>(uint)b ? 1:0; break;
                        case Operation.LessUnsigned: stack[sp++] = (uint)a<(uint)b ? 1:0; break;
                        case Operation.Eq: if(a==b) pc=operand; break;
                        case Operation.Ne: if(a!=b) pc=operand; break;
                        case Operation.Ge: if(a>=b) pc=operand; break;
                        case Operation.Gt: if(a>b) pc=operand; break;
                        case Operation.Le: if(a<=b) pc=operand; break;
                        case Operation.Lt: if(a<b) pc=operand; break;
                        case Operation.GeUnsigned: if((uint)a>=(uint)b) pc=operand; break;
                        case Operation.GtUnsigned: if((uint)a>(uint)b) pc=operand; break;
                        case Operation.LeUnsigned: if((uint)a<=(uint)b) pc=operand; break;
                        case Operation.LtUnsigned: if((uint)a<(uint)b) pc=operand; break;
                        case Operation.AddChecked: stack[sp++] = checked(a+b); break;
                        case Operation.SubChecked: stack[sp++] = checked(a-b); break;
                        case Operation.MulChecked: stack[sp++] = checked(a*b); break;
                        case Operation.AddCheckedUnsigned: stack[sp++] = unchecked((int)checked(unchecked((uint)a)+unchecked((uint)b))); break;
                        case Operation.SubCheckedUnsigned: stack[sp++] = unchecked((int)checked(unchecked((uint)a)-unchecked((uint)b))); break;
                        case Operation.MulCheckedUnsigned: stack[sp++] = unchecked((int)checked(unchecked((uint)a)*unchecked((uint)b))); break;
                        default: throw new System.InvalidOperationException("Invalid Durevo program.");
                    }
                    break;
            }
        }
    }

    private static string Text(string[] strings, int token) =>
        token == 0 ? throw new System.NullReferenceException() : strings[token - 1];

    private static int Decode(int[] program, int index, int key) =>
        program[index] ^ unchecked(key + index * (int)0x9e3779b9);
}
